from __future__ import annotations

from trace_models import TraceSpan


def _trace_key(span: TraceSpan) -> str:
    return span.local_task_id


def _span_dict(span: TraceSpan) -> dict[str, object]:
    return {
        "span_id": span.span_id,
        "subsystem": span.subsystem,
        "region": span.region,
        "local_task_id": span.local_task_id,
        "correlation_id": span.correlation_id,
        "operation": span.operation,
        "duration_ms": span.duration_ms,
        "wait_reason": span.wait_reason,
    }


def _trace_report(trace_id: str, spans: list[TraceSpan]) -> dict[str, object]:
    bottleneck = max(spans, key=lambda span: span.duration_ms)
    return {
        "trace_id": trace_id,
        "total_duration_ms": sum(span.duration_ms for span in spans),
        "bottleneck_subsystem": bottleneck.subsystem,
        "bottleneck_reason": bottleneck.wait_reason,
        "span_ids": [span.span_id for span in spans],
        "spans": [_span_dict(span) for span in spans],
    }


def correlate_mainframe_traces(spans: list[TraceSpan]) -> dict[str, object]:
    traces: dict[str, list[TraceSpan]] = {}
    audit_warnings: list[dict[str, object]] = []

    for span in spans:
        if span.correlation_id is None:
            audit_warnings.append(
                {
                    "span_id": span.span_id,
                    "warning": "missing_correlation_id",
                    "subsystem": span.subsystem,
                    "local_task_id": span.local_task_id,
                }
            )
            continue
        key = _trace_key(span)
        traces.setdefault(key, []).append(span)

    reports = [_trace_report(trace_id, trace_spans) for trace_id, trace_spans in traces.items()]
    return summarize_trace_report(reports, audit_warnings)


def summarize_trace_report(
    traces: list[dict[str, object]],
    audit_warnings: list[dict[str, object]],
) -> dict[str, object]:
    sorted_traces = sorted(
        traces,
        key=lambda trace: (-int(trace["total_duration_ms"]), str(trace["trace_id"])),
    )
    return {
        "trace_count": len(sorted_traces),
        "audit_warning_count": len(audit_warnings),
        "traces": sorted_traces,
        "audit_warnings": audit_warnings,
    }


class MainframeTraceCorrelator:
    def correlate(self, spans: list[TraceSpan]) -> dict[str, object]:
        return correlate_mainframe_traces(spans)

