from __future__ import annotations

from dataclasses import dataclass


VALID_SUBSYSTEMS = {"CICS", "DB2", "MQ"}


@dataclass(frozen=True)
class TraceSpan:
    span_id: str
    subsystem: str
    region: str
    local_task_id: str
    correlation_id: str | None
    operation: str
    duration_ms: int
    wait_reason: str | None = None

    def __post_init__(self) -> None:
        if not self.span_id.strip():
            raise ValueError("span_id required")
        if self.subsystem not in VALID_SUBSYSTEMS:
            raise ValueError("unsupported subsystem")
        if not self.region.strip():
            raise ValueError("region required")
        if not self.local_task_id.strip():
            raise ValueError("local_task_id required")
        if self.correlation_id is not None and not self.correlation_id.strip():
            raise ValueError("correlation_id cannot be blank")
        if not self.operation.strip():
            raise ValueError("operation required")
        if self.duration_ms < 0:
            raise ValueError("duration_ms must be non-negative")

